def f1(i,o):
    g=[]
    for bi in range(0,24,3):
        row=[]
        for bj in range(0,24,3):
            vals=[i[bi+di][bj+dj] for di in range(3) for dj in range(3)]
            cnt={}
            for v in vals:
                if v!=5: cnt[v]=cnt.get(v,0)+1
            # pick largest count; tie -> min key
            if not cnt: row.append(5); continue
            c=max(cnt.values()); row.append(min(k for k,cnt[k]==c))
        g.append(row)
    return g==o
